import requests

response = requests.post(
    "https://api.aimlapi.com/v1/stt/create",
    headers={
        "Authorization": "Bearer <YOUR_AIMLAPI_KEY>",
        "Content-Type": "application/json",
    },
    json={'model': 'elevenlabs/scribe_v2'},
)

print(response.json())
